"use strict";(globalThis.webpackChunknemerald_web=globalThis.webpackChunknemerald_web||[]).push([[3344],{67141(e){e.exports=JSON.parse('{"tag":{"label":"desktop","permalink":"/docs/tags/desktop","allTagsPath":"/docs/tags","count":38,"items":[{"id":"apps/ringotel/desktop-app/general/desktop-audio-settings--a9uwhby2gvts8tp969uze2yw","title":"Audio settings","description":"1. Jitter buffer length control (helps to improve call quality in case of unstable internet connections).","permalink":"/docs/apps/desktop-audio-settings--a9uwhby2gvts8tp969uze2yw"},{"id":"apps/ringotel/desktop-app/general/desktop-blocklist--a279g7muy8kgbywr1ja8zwdo","title":"Block phone numbers","description":"Looking for an&#x20;Android or&#x20;iOS version of this article?","permalink":"/docs/apps/desktop-blocklist--a279g7muy8kgbywr1ja8zwdo"},{"id":"apps/ringotel/desktop-app/general/desktop-call-parking--plo8imk946vya1f7dapzaatq","title":"Call parking","description":"Availability of this feature depends on your service configuration. Contact support for details.","permalink":"/docs/apps/desktop-call-parking--plo8imk946vya1f7dapzaatq"},{"id":"apps/ringotel/desktop-app/general/desktop-call-settings--w8x57mdttk6m2ucvcxpao23m","title":"Call Settings","description":"Looking for an&#x20;Android or&#x20;iOS version of this article?","permalink":"/docs/apps/desktop-call-settings--w8x57mdttk6m2ucvcxpao23m"},{"id":"apps/ringotel/desktop-app/general/desktop-call-transfer--goxhybvy8g83rnreyy2bsadr","title":"Call transfer","description":"Looking for an&#x20;Android or&#x20;iOS version of this article?","permalink":"/docs/apps/desktop-call-transfer--goxhybvy8g83rnreyy2bsadr"},{"id":"apps/ringotel/desktop-app/general/desktop-chats-and-messages--s2tpb7mo6h2emho461usba3h","title":"Chats and messages overview","description":"Availability of this feature depends on your service configuration. Contact support for details.","permalink":"/docs/apps/desktop-chats-and-messages--s2tpb7mo6h2emho461usba3h"},{"id":"apps/ringotel/desktop-app/general/desktop-contacts-and-users-tabs--hrbdi37d949mb152d0llrw4p","title":"Contacts and Users overview","description":"In the Users tab, you can see all your colleagues with their presence statuses.","permalink":"/docs/apps/desktop-contacts-and-users-tabs--hrbdi37d949mb152d0llrw4p"},{"id":"apps/ringotel/desktop-app/general/desktop-creating-chat-sms--wq59474ron4rofgdi73acjxw","title":"Creating a chat / Sending SMS","description":"Availability of this feature depends on your service configuration. Contact support for details.","permalink":"/docs/apps/desktop-creating-chat-sms--wq59474ron4rofgdi73acjxw"},{"id":"apps/ringotel/desktop-app/general/desktop-creating-group-chat--im5eg24mu3srsmufop1eml2m","title":"Creating a group chat","description":"To create a group chat:","permalink":"/docs/apps/desktop-creating-group-chat--im5eg24mu3srsmufop1eml2m"},{"id":"apps/ringotel/desktop-app/general/desktop-remove-chat-history--rdwi3npuq7nrgxv32e21wvf5","title":"Deleting chat history and messages","description":"To remove a message:","permalink":"/docs/apps/desktop-remove-chat-history--rdwi3npuq7nrgxv32e21wvf5"},{"id":"apps/ringotel/desktop-app/general/desktop-user-interface--ophgjz3guikdjfl0oga2h6t5","title":"Desktop app overview","description":"After you\u2019ve logged into the app, you\u2019ll see a user interface as shown in a screenshot below:","permalink":"/docs/apps/desktop-user-interface--ophgjz3guikdjfl0oga2h6t5"},{"id":"apps/ringotel/desktop-app/general/desktop-call-hold-dtmf-recording--ybm4k618ragnlgyy963xbwpe","title":"During a call: Hold, DTMF, Recording","description":"During a call, you can transfer a call, put a call on hold, create a conference, and much more. You can access those features by utilizing the UI components described below:","permalink":"/docs/apps/desktop-call-hold-dtmf-recording--ybm4k618ragnlgyy963xbwpe"},{"id":"apps/ringotel/desktop-app/general/enabling-click-to-call-windows--g7q0d48cwa9en8tqf0w25io2","title":"Enabling Click-to-Call (Windows)","description":"The click-to-call (or click-to-dial) feature lets you dial phone numbers by clicking specially formatted links on websites, CRM or other web or native applications.","permalink":"/docs/apps/enabling-click-to-call-windows--g7q0d48cwa9en8tqf0w25io2"},{"id":"apps/ringotel/desktop-app/general/desktop-general-app-settings--g4g5p30bgtm5ofmc1sxsa040","title":"General App Settings","description":"You can configure a pop-up window during incoming calls and voicemails, trigger auto-recording of all calls as well as set the storage location for records in the General section. All forwarding rules, as well as enabling the possibility to receive a second call can be set in Call settings. Device selection for speakers and microphone in the Audio section. All camera-related features for video calls can be found in the Video section.","permalink":"/docs/apps/desktop-general-app-settings--g4g5p30bgtm5ofmc1sxsa040"},{"id":"apps/ringotel/desktop-app/general/highlight-to-call--pbaho2fe7qwn2loazhijmdq3","title":"Highlight-To-Call","description":"The Highlight-To-Call feature allows you to highlight a phone number anywhere on the computer screen and automatically make a call via the Softphone app on Windows.","permalink":"/docs/apps/highlight-to-call--pbaho2fe7qwn2loazhijmdq3"},{"id":"apps/ringotel/desktop-app/general/desktop-add-delete-contact--ahhk0yl59mshn5v92dpmdk3o","title":"How to add and delete a contact","description":"You can add personal external contacts to your contacts list. The details of such contacts will be available to you only.","permalink":"/docs/apps/desktop-add-delete-contact--ahhk0yl59mshn5v92dpmdk3o"},{"id":"apps/ringotel/desktop-app/general/desktop-add-notes-to-call--ny22ugui8gmkhqsd09qcgely","title":"How to add notes to a call","description":"Your desktop app allows you to add additional notes to each call. You can add a call purpose and add comments with the details of your conversations.","permalink":"/docs/apps/desktop-add-notes-to-call--ny22ugui8gmkhqsd09qcgely"},{"id":"apps/ringotel/desktop-app/general/desktop-login-screen--z1hnjyua9dewdivc7n2zsjzj","title":"How to log in to the app","description":"To start using the app on your Mac or Windows PC, click on the app iconApp iconin the launchpad (Mac) or Start menu (Windows). Then enter the authentication parameters in the email you received from your PBX Admin, as shown below.","permalink":"/docs/apps/desktop-login-screen--z1hnjyua9dewdivc7n2zsjzj"},{"id":"apps/ringotel/desktop-app/general/desktop-start-working-with-app--a7ufngmkbmmo2vbz2fpk7zne","title":"How to start working with your Desktop App","description":"Looking for aniOSorAndroidversion of this article?","permalink":"/docs/apps/desktop-start-working-with-app--a7ufngmkbmmo2vbz2fpk7zne"},{"id":"apps/ringotel/desktop-app/general/desktop-list-of-hotkeys--pwsmbmo8xheebiwps6k9rs9n","title":"List of hotkeys","description":"You can view all the available hotkeys in the Hotkeys settings tab.","permalink":"/docs/apps/desktop-list-of-hotkeys--pwsmbmo8xheebiwps6k9rs9n"},{"id":"apps/ringotel/desktop-app/general/desktop-managing-participants-group-chat--ukkr7jatj40gz9st8lyo41j1","title":"Managing participants in a group chat","description":"Adding/removing users in a group chat","permalink":"/docs/apps/desktop-managing-participants-group-chat--ukkr7jatj40gz9st8lyo41j1"},{"id":"apps/ringotel/desktop-app/general/desktop-outgoing-call--te63hnixsyugdk7wpsw59xeq","title":"Outgoing call","description":"There are several ways you can make an outgoing call from the desktop app:","permalink":"/docs/apps/desktop-outgoing-call--te63hnixsyugdk7wpsw59xeq"},{"id":"apps/ringotel/desktop-app/general/remove-participants-from-a-conference-windows-mac-desktop--nppp2oyqarg76q5ssezwxwp9","title":"Remove participants from a conference","description":"Looking for an&#x20;iOS or&#x20;Android version of this article?","permalink":"/docs/apps/remove-participants-from-a-conference-windows-mac-desktop--nppp2oyqarg76q5ssezwxwp9"},{"id":"apps/ringotel/desktop-app/general/desktop-replying-to-message--xynwl92hdguut0gqq2ooav40","title":"Replying to a message","description":"Replying with a quotation is used when you want to reply to a specific message in a chat.","permalink":"/docs/apps/desktop-replying-to-message--xynwl92hdguut0gqq2ooav40"},{"id":"apps/ringotel/desktop-app/general/desktop-search-in-chat--gvsa3sl8prnrklk78m3rqu5a","title":"Search in a chat","description":"You can search for information in chat using various filters:","permalink":"/docs/apps/desktop-search-in-chat--gvsa3sl8prnrklk78m3rqu5a"},{"id":"apps/ringotel/desktop-app/general/desktop-sending-a-file--mzk5c5g9pe8qbyvndhgitl3t","title":"Sending a file","description":"To send a file:","permalink":"/docs/apps/desktop-sending-a-file--mzk5c5g9pe8qbyvndhgitl3t"},{"id":"apps/ringotel/desktop-app/general/desktop-sending-voice-message--xc1je2z474z6tgyiqm5fxcdq","title":"Sending a voice message","description":"To send a voice message:","permalink":"/docs/apps/desktop-sending-voice-message--xc1je2z474z6tgyiqm5fxcdq"},{"id":"apps/ringotel/desktop-app/general/desktop-sharing-messages--owglr8brvep0mwome8f0t0kq","title":"Sharing messages","description":"To share a message, file, or call record from one chat to another:","permalink":"/docs/apps/desktop-sharing-messages--owglr8brvep0mwome8f0t0kq"},{"id":"apps/ringotel/desktop-app/general/desktop-speed-dial--p0ucqp38ff7htcgyyifjafjb","title":"Speed Dial overview","description":"Speed dial list can contain phone numbers for a one-click call and indicators showing states of various features of your phone system.","permalink":"/docs/apps/desktop-speed-dial--p0ucqp38ff7htcgyyifjafjb"},{"id":"apps/ringotel/desktop-app/general/desktop-conference-calls--vaqva2dc377xnjga0me78u8p","title":"Starting a conference call","description":"Looking for aniOSorAndroidversion of this article?","permalink":"/docs/apps/desktop-conference-calls--vaqva2dc377xnjga0me78u8p"},{"id":"apps/ringotel/desktop-app/general/desktop-user-presence-states--oebvyc1xlqd7yyz6dqtouz0q","title":"User presence status","description":"With the help of various user statuses your mobile app allows you to share your availability with the team and check the availability of your colleagues. There are 5 different states a user can have:","permalink":"/docs/apps/desktop-user-presence-states--oebvyc1xlqd7yyz6dqtouz0q"},{"id":"apps/ringotel/desktop-app/general/desktop-video-settings--skf51aul86q7qafdn0bcljku","title":"Video settings","description":"1. Turn on your video camera for testing.","permalink":"/docs/apps/desktop-video-settings--skf51aul86q7qafdn0bcljku"},{"id":"apps/ringotel/desktop-app/general/desktop-viewing-editing-contact-details--odrg8cogkt9glqqssm4isgzj","title":"Viewing and editing contact details","description":"To view or edit contact details, click on the iconApp iconin the upper right corner of the chat panel.","permalink":"/docs/apps/desktop-viewing-editing-contact-details--odrg8cogkt9glqqssm4isgzj"},{"id":"apps/ringotel/desktop-app/general/desktop-call-history--v2k1i9nh4bq89509p5nm99bv","title":"Viewing call history","description":"You can view the history of all your incoming and outgoing calls through the Calls tab .","permalink":"/docs/apps/desktop-call-history--v2k1i9nh4bq89509p5nm99bv"},{"id":"apps/ringotel/desktop-app/general/desktop-voicemail--dqa3qfyebvyy59cyk38biu10","title":"Voicemail settings","description":"In case when you\u2019re unable to pick up a call, you can send it to a voicemail. It can be enabled in your desktop app or by your PBX administrator.","permalink":"/docs/apps/desktop-voicemail--dqa3qfyebvyy59cyk38biu10"},{"id":"apps/ringotel/android-app/general/android-working-with-call-details--skwusuj0tgk0s8mw74vudu53","title":"Working with call details","description":"When you make dozens of calls every day, it is very hard to remember the details of every single call. By filling in a call subject and adding some comments, you can highlight the most important parts of your conversation and easily find them later, when you\u2019ll need them.","permalink":"/docs/apps/android-working-with-call-details--skwusuj0tgk0s8mw74vudu53"},{"id":"apps/ringotel/desktop-app/general/desktop-working-with-call-recordings--ssv2vm6rzstcim2xd99giaun","title":"Working with call recordings","description":"Availability of this feature depends on your service configuration. Contact support for details.","permalink":"/docs/apps/desktop-working-with-call-recordings--ssv2vm6rzstcim2xd99giaun"},{"id":"apps/ringotel/desktop-app/general/desktop-incoming-call--n22xzs69gy36sp3f9hpdds40","title":"Working with incoming call","description":"When you receive an incoming call:","permalink":"/docs/apps/desktop-incoming-call--n22xzs69gy36sp3f9hpdds40"}],"unlisted":false}}')}}]);